package com.croxnovaspace;

import java.util.HashMap;
import java.util.Map;

// Generated at build time from the wrapped site's HTML/CSS/JS. Each
// file's bytes are stored base64-encoded as a compiled string constant
// (part of classes.dex), not as a loose file under assets/.
// MainActivity's shouldInterceptRequest override (see EMBED_HOST) decodes
// these on demand to feed the WebView, in place of the OS resolving
// file:///android_asset/ requests against a real assets/ folder.
// Additionally AES-encrypted -- see AssetCrypto -- so the decoded bytes
// aren't the real file content until AssetCrypto.decrypt() runs on them.
public final class EmbeddedAssets {
    // Joins base64 chunks at class-init time. Deliberately NOT string
    // concatenation on the call site (see the comment above each F<n>
    // field) -- a method call is not a compile-time constant expression,
    // so javac can't fold these chunks back into one oversized constant.
    private static String join(String... parts) {
        StringBuilder sb = new StringBuilder();
        for (String p : parts) sb.append(p);
        return sb.toString();
    }

    private static final String F0 = join(
            "");

    private static final String F1 = join(
            "");

    private static final String F2 = join(
            "");

    private static final String F3 = join(
            "",
            "");

    private static final String F4 = join(
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "");

    private static final String F5 = join(
            "",
            "",
            "",
            "");

    private static final String F6 = join(
            "",
            "");

    private static final String F7 = join(
            "");

    private static final String F8 = join(
            "");

    private static final String F9 = join(
            "");

    private static final Map<String, String> MAP = new HashMap<>();
    static {
        MAP.put(UrlObfuscator.decode(new int[] { 125, 11, 44, 200, 230, 143, 199, 124, 95, 50 }, 47), F0);
        MAP.put(UrlObfuscator.decode(new int[] { 33, 44, 13, 248, 200, 168, 213, 110, 79, 32, 89, 252, 218, 183, 151, 105, 30, 39, 26, 224, 192 }, 64), F1);
        MAP.put(UrlObfuscator.decode(new int[] { 48, 3, 252, 203, 185, 159, 36, 93, 62, 31, 168, 197, 182, 151, 44, 76, 46, 22, 30, 237, 205, 189, 152, 127, 20, 55, 1, 243, 199, 188, 146, 103, 93, 126, 12, 253, 222 }, 81), F2);
        MAP.put(UrlObfuscator.decode(new int[] { 3, 242, 211, 218, 170, 142, 51, 76, 45, 14, 183, 212, 165, 134, 59, 64, 38, 8, 252, 202, 189, 195, 111, 88, 57 }, 98), F3);
        MAP.put(UrlObfuscator.decode(new int[] { 18, 225, 194, 181, 155, 125, 2, 59, 28, 253, 134, 161, 138, 97, 10, 42, 12, 244, 192, 179, 175, 159, 126, 89, 118, 25, 246, 203, 186, 159, 118, 25, 36, 19, 253, 220, 191, 143, 125, 73, 57, 68, 249, 198, 160 }, 115), F4);
        MAP.put(UrlObfuscator.decode(new int[] { 229, 208, 177, 132, 116, 108, 17, 42, 11, 236, 149, 179, 139, 56, 87, 37, 4, 224, 156, 187, 131 }, 132), F5);
        MAP.put(UrlObfuscator.decode(new int[] { 244, 199, 160, 151, 101, 67, 96, 25, 250, 219, 228, 128, 122, 7, 37, 19, 231, 198, 175, 135, 47, 74, 76 }, 149), F6);
        MAP.put(UrlObfuscator.decode(new int[] { 199, 182, 151, 102, 86, 50, 79, 8, 233, 202, 243, 145, 105, 22, 52, 30, 241, 221, 160, 135, 125, 94, 60, 28, 163, 207, 190, 130, 110, 78, 45, 73, 236, 214 }, 166), F7);
        MAP.put(UrlObfuscator.decode(new int[] { 214, 165, 134, 113, 71, 33, 94, 231, 216, 185, 194, 102, 88, 101, 4, 233, 206, 168, 203, 110, 80 }, 183), F8);
        MAP.put(UrlObfuscator.decode(new int[] { 169, 148, 117, 64, 48, 16, 173, 214, 183, 168, 209, 119, 79, 116, 13, 244, 150, 189, 133 }, 200), F9);
    }

    // rel: path as it would have appeared under assets/, e.g. "index.html"
    // or "css/style.css". Returns null if nothing was embedded at that path.
    public static byte[] get(String rel) {
        String b64 = MAP.get(rel);
        if (b64 == null) return null;
        byte[] raw = android.util.Base64.decode(b64, android.util.Base64.DEFAULT);
        return AssetCrypto.decrypt(raw);
    }

    private EmbeddedAssets() {}
}
